let crmSettings={organization:'GrantEd',year:2027,currentUser:null,teamCount:0},crmTeam=null;
const passwordField=(name,label)=>`<label>${label}<input type="password" name="${name}" required minlength="${name==='currentPassword'?1:12}" maxlength="256" autocomplete="${name==='currentPassword'?'current-password':'new-password'}"></label>`;
const formatInviteDate=value=>new Date(value).toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'});

function teamMarkup(){
 if(!crmTeam)return '<p class="subtle">Загрузка команды…</p>';
 const staff=crmTeam.staff.map(member=>`<tr><td><div class="person"><span class="avatar">${esc(member.name.split(/\s+/).map(part=>part[0]).slice(0,2).join(''))}</span><div><strong>${esc(member.name)}</strong><small>${esc(member.email)}</small></div></div></td><td><span class="badge ${member.status==='active'?'green':''}">${member.status==='active'?'Активен':'Отключён'}</span></td><td>${formatInviteDate(member.createdAt)}</td><td><button data-team-status="${member.status==='active'?'disabled':'active'}" data-id="${member.id}">${member.status==='active'?'Отключить':'Включить'}</button></td></tr>`).join('');
 const invitations=crmTeam.invitations.map(invite=>`<tr><td><div class="person"><span class="avatar">…</span><div><strong>${esc(invite.name)}</strong><small>${esc(invite.email)}</small></div></div></td><td><span class="badge amber">Ожидает</span></td><td>до ${formatInviteDate(invite.expires)}</td><td><button data-team-revoke data-id="${invite.id}">Отозвать</button></td></tr>`).join('');
 return `<div class="team-summary"><strong>${crmTeam.used} из ${crmTeam.limit}</strong><span>мест занято активными сотрудниками и приглашениями</span></div><div class="tablewrap"><table><thead><tr><th>Сотрудник</th><th>Статус</th><th>Добавлен</th><th></th></tr></thead><tbody>${staff}${invitations}${!staff&&!invitations?'<tr><td colspan="4"><div class="empty">Пока нет сотрудников. Отправьте первое приглашение.</div></td></tr>':''}</tbody></table></div>`;
}

async function loadTeam(){if(crmSettings.currentUser?.role!=='owner')return;try{crmTeam=await api('/api/team');crmSettings.teamCount=crmTeam.used;const target=$('#team-list');if(target)target.innerHTML=teamMarkup()}catch(error){const target=$('#team-list');if(target)target.innerHTML=`<p class="error">${esc(error.message)}</p>`}}

function renderSettings(){
 const user=crmSettings.currentUser||crmUser||{},owner=user.role==='owner';
 const workspace=owner?`<section class="settings-section"><h2>Рабочее пространство</h2><form data-settings="profile"><label>Имя владельца<input name="name" required maxlength="100" value="${esc(crmSettings.name||user.name||'')}"></label><label>Название организации<input name="organization" required maxlength="100" value="${esc(crmSettings.organization)}"></label><label>Год набора по умолчанию<input type="number" name="year" min="2020" max="2100" required value="${crmSettings.year}"></label><p class="subtle">Новый год применяется к новым карточкам.</p><p class="form-status" role="status"></p><button class="primary">Сохранить настройки</button></form></section>`:`<section class="settings-section"><h2>Рабочее пространство</h2><p><strong>${esc(crmSettings.organization)}</strong></p><p>Цикл поступления: набор ${esc(crmSettings.year)}</p><p class="subtle">Основные настройки меняет владелец.</p></section>`;
 const account=`<section class="settings-section"><h2>Ваш вход</h2><p>${esc(user.name||'')}</p><p>Почта: <strong>${esc(user.email||'')}</strong></p><form data-settings="password">${passwordField('currentPassword','Текущий пароль')}${passwordField('newPassword','Новый пароль — минимум 12 символов')}${passwordField('confirmPassword','Повторите новый пароль')}<p class="subtle">После смены пароля текущие сессии будут завершены.</p><p class="form-status" role="status"></p><button>Изменить пароль</button></form></section>`;
 const recovery=owner?`<section class="settings-section"><h2>Восстановление владельца</h2><p>${crmSettings.recoveryEnabled?'Резервный код создан.':'Резервный код пока не создан.'} Храните его отдельно от CRM.</p><form data-settings="recovery">${passwordField('currentPassword','Текущий пароль')}<p class="subtle">Новый код отменяет предыдущий и показывается один раз.</p><p class="form-status" role="status"></p><button>Создать резервный код</button></form><div id="recovery-result"></div></section>`:'';
 const data=owner?`<section class="settings-section"><h2>Данные и подключения</h2><p>Выгрузка содержит карточки, заявки, задачи и отчёты.</p><a class="quiet-link" href="/api/export">Скачать JSON</a><p><a href="#integrations">Управлять Google Drive и Gmail</a></p></section>`:'';
 const team=owner?`<section class="settings-section team-section"><div class="section-top"><div><h2>Команда</h2><p class="subtle">До 10 сотрудников с личным входом.</p></div></div><form data-settings="invite" class="invite-form"><label>Имя сотрудника<input name="name" required maxlength="100" placeholder="Имя и фамилия"></label><label>Рабочая почта<input name="email" type="email" required maxlength="254" placeholder="name@company.kz"></label><button class="primary">Отправить приглашение</button><p class="form-status" role="status"></p></form><div id="invite-result"></div><div id="team-list">${teamMarkup()}</div></section>`:'';
 $('#app').innerHTML=shell(`<div class="heading"><div><h1>Настройки</h1><p>Рабочее пространство, команда и безопасность входа.</p></div></div><div class="settings-grid">${workspace}${account}${recovery}${data}${team}</div>`,'settings');loadTeam();
}

document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.dataset.settings)return;event.preventDefault();
 const data=Object.fromEntries(new FormData(form)),kind=form.dataset.settings,status=form.querySelector('.form-status'),button=form.querySelector('button');button.disabled=true;status.textContent=kind==='invite'?'Отправка…':'Сохранение…';
 try{
  if(kind==='profile'){await api('/api/settings',{method:'PUT',body:JSON.stringify({...data,year:Number(data.year)})});crmSettings=await api('/api/settings');crmUser=crmSettings.currentUser;renderSettings();toast('Настройки сохранены')}
  if(kind==='password'){if(data.newPassword!==data.confirmPassword)throw Error('Новые пароли не совпадают.');await api('/api/auth/password',{method:'POST',body:JSON.stringify(data)});clients=[];location.hash='';showLogin(true);toast('Пароль изменён. Войдите заново.')}
  if(kind==='recovery'){const result=await api('/api/auth/recovery-code',{method:'POST',body:JSON.stringify(data)});crmSettings.recoveryEnabled=true;form.reset();status.textContent='Новый код создан.';$('#recovery-result').innerHTML=`<div class="notice"><strong>Сохраните этот код сейчас</strong><p><code class="recovery-code">${esc(result.code)}</code></p><p>После ухода со страницы код больше не будет показан.</p></div>`}
  if(kind==='invite'){const result=await api('/api/team/invitations',{method:'POST',body:JSON.stringify(data)});form.reset();status.textContent=result.sent?'Приглашение отправлено на email.':'Приглашение создано, но автоматическая отправка ещё не настроена.';$('#invite-result').innerHTML=result.sent?`<div class="notice"><strong>Письмо отправлено</strong><p>${esc(result.email)} получит одноразовую ссылку, действующую 7 дней.</p></div>`:`<div class="notice"><strong>Скопируйте ссылку сотруднику</strong><p class="invite-link">${esc(result.inviteUrl)}</p><button type="button" data-copy-invite="${esc(result.inviteUrl)}">Скопировать ссылку</button>${result.warning?`<p class="error">${esc(result.warning)}</p>`:''}</div>`;await loadTeam()}
 }catch(error){status.textContent=error.message}finally{button.disabled=false}
});

document.addEventListener('click',async event=>{
 const statusButton=event.target.closest('[data-team-status]'),revokeButton=event.target.closest('[data-team-revoke]'),copyButton=event.target.closest('[data-copy-invite]');
 if(copyButton){try{await navigator.clipboard.writeText(copyButton.dataset.copyInvite);toast('Ссылка скопирована')}catch{toast('Не удалось скопировать. Выделите ссылку вручную.')}return}
 if(!statusButton&&!revokeButton)return;const button=statusButton||revokeButton;button.disabled=true;
 try{crmTeam=await api(statusButton?'/api/team/status':'/api/team/invitations/revoke',{method:'POST',body:JSON.stringify(statusButton?{id:button.dataset.id,status:button.dataset.teamStatus}:{id:button.dataset.id})});crmSettings.teamCount=crmTeam.used;$('#team-list').innerHTML=teamMarkup();toast(statusButton?(button.dataset.teamStatus==='active'?'Доступ сотрудника включён':'Доступ сотрудника отключён'):'Приглашение отозвано')}catch(error){toast(error.message)}finally{button.disabled=false}
});

document.addEventListener('click',event=>{
 if(event.target.closest('[data-back-login]')){location.hash='';showLogin(true)}
 if(!event.target.closest('[data-recover]'))return;
 $('#app').innerHTML=`<main class="recovery-page"><h1>Восстановить пароль владельца</h1><p>Введите почту владельца и резервный код.</p><form id="recover-form"><label>Почта<input name="email" type="email" required autocomplete="username"></label><label>Резервный код<input name="code" required maxlength="200" autocomplete="off" spellcheck="false"></label>${passwordField('newPassword','Новый пароль — минимум 12 символов')}${passwordField('confirmPassword','Повторите новый пароль')}<p class="form-status" role="alert"></p><button class="primary">Восстановить доступ</button></form><p><button data-back-login>Вернуться ко входу</button></p></main>`;
 $('#recover-form').onsubmit=async submit=>{submit.preventDefault();const form=submit.target,data=Object.fromEntries(new FormData(form)),button=form.querySelector('button');button.disabled=true;try{if(data.newPassword!==data.confirmPassword)throw Error('Новые пароли не совпадают.');await api('/api/auth/recover',{method:'POST',body:JSON.stringify(data)});showLogin(true);toast('Пароль восстановлен.')}catch(error){form.querySelector('.form-status').textContent=error.message}finally{button.disabled=false}};
});
